/* Start custom CSS for container, class: .elementor-element-3db8d240 *//* Container for the split image effect */
.split-image {
  position: relative;
  display: block;
  width: 320px;
  height: 200px;
  overflow: hidden;
}

.split-image img {
  width: 360px;
  height: auto;
  display: block;
  opacity: 0.9; /* Overall opacity for the image */
  transition: opacity 0.3s ease-in-out;
}

/* Create the split effect */
.split-image::before, .split-image::after {
  content: "";
  position: absolute;
  background: rgba(255, 255, 255, 0.6); /* White overlay */
  mix-blend-mode: screen; /* Blend mode for overlay effect */
  transition: transform 0.3s ease-in-out;
}

/* Top and bottom parts of the split */
.split-image::before {
  top: 0;
  left: 0;
  width: 50%;
  height: 50%;
  transform: translate(-10px, -10px); /* Adjust positioning for overlap effect */
}

.split-image::after {
  bottom: 0;
  right: 0;
  width: 50%;
  height: 50%;
  transform: translate(10px, 10px); /* Adjust positioning for overlap effect */
}

/* Hover effect */
.split-image:hover img {
  opacity: 1;
}

.split-image:hover::before, 
.split-image:hover::after {
  transform: translate(0, 0);
}/* End custom CSS */
